"""
Kaggle GPU job: build the unpruned corpus (torch/generate_corpus.py), SPEC 0.5.

MODE = "smoke": 2 prompts (1 MusicCaps + 1 red-team) and a CMI-RM probe (judge timebox).
MODE = "full":  all 50 prompts. Resumable per prompt within a session.

Sources are embedded below; refresh before pushing:
  python kaggle_job/bundle.py kaggle_corpus && uvx kaggle kernels push -p kaggle_corpus

Judge scores beyond Audiobox are a second pass over wavs.tar: see kaggle_judge/run.py.
Do not re-push this kernel: a new version replaces the outputs kaggle_judge reads.
Outputs in /kaggle/working: corpus/<id>.json + <id>.tokens.npy, wavs.tar (all WAVs),
env*.txt, cmi_probe.log, corpus.log, cmi_score.log, summary.json.
"""
import json, subprocess, sys, time
from pathlib import Path

MODE = "full"
USE_CMI = False  # CMI-RM missed its 1 h timebox (tasks/decisions.md); Audiobox is the judge
SMOKE_IDS = ["mc_7-mNJ4IUY5Q", "rt_00"]
OUT = Path("/kaggle/working") if Path("/kaggle/working").exists() else Path.cwd()
SRC = OUT / "src"
CMI = Path("/tmp/CMI-RewardBench")    # not under /kaggle/working: kept out of the outputs
VENV = Path("/tmp/cmienv")             # CMI-RM needs transformers 4.57; generation uses 5.17
VPY = str(VENV / "bin/python")
PY = sys.executable
PIP = [PY, "-m", "pip", "install", "-q"]
TORCH_V = [PY, "-c", "import torch, transformers; print(torch.__version__, transformers.__version__)"]
CMI_PROBE = f"""
import sys, time, numpy as np
sys.path.insert(0, "{SRC}/torch")
from scorers import CmiRm
t = time.time()
m = CmiRm("{CMI}", "{CMI}/baselines/model/model.safetensors")
rng = np.random.default_rng(0)
w = [0.1 * np.sin(2 * np.pi * 440 * np.arange(32000 * 30) / 32000).astype(np.float32),
     0.1 * rng.standard_normal(32000 * 30).astype(np.float32)]
print("CMI-RM scores (sine, noise):", m(w, "a calm piano melody"), f"{{time.time() - t:.1f}}s")
"""


def sh(cmd, log=None, cwd=OUT):
    """Run cmd, tee output to OUT/log, return exit code."""
    lines = []
    p = subprocess.Popen(cmd, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
    for line in p.stdout:
        print(line, end="", flush=True); lines.append(line)
    rc = p.wait()
    if log:
        (OUT / log).write_text("".join(lines))
    return rc


def main():
    t0, summary = time.time(), {"mode": MODE}
    for name, text in SOURCES.items():
        (SRC / name).parent.mkdir(parents=True, exist_ok=True)
        (SRC / name).write_text(text)
    sh(TORCH_V, "env_before.txt")
    summary["pip"] = sh(PIP + ["transformers==5.17.0", "audiobox_aesthetics"])
    # CMI-RM: venv sharing Kaggle's torch, with its own transformers 4.57.3 + extras
    summary["cmi_setup"] = USE_CMI and (
        sh(["git", "clone", "-q", "--depth", "1", "https://github.com/Haiwen-Xia/CMI-RewardBench", str(CMI)])
        or sh([PY, "-m", "venv", "--system-site-packages", str(VENV)])
        or sh([VPY, "-m", "pip", "install", "-q", "transformers==4.57.3", "einops", "librosa", "nnAudio",
               "easydict", "x-clip", "omegaconf"])
        or sh([PY, "-c", "from huggingface_hub import snapshot_download as d; "
               f"print(d('HaiwenXia/CMI-RM', local_dir='{CMI}/baselines/model'))"]))
    sh(["bash", "-c", "nvidia-smi --query-gpu=name,memory.total --format=csv"], "env.txt")
    sh(TORCH_V, "env_after.txt")
    summary["env_before"] = (OUT / "env_before.txt").read_text().strip()
    summary["env_after"] = (OUT / "env_after.txt").read_text().strip()
    summary["cmi_ok"] = USE_CMI and summary["cmi_setup"] == 0 and sh([VPY, "-c", CMI_PROBE], "cmi_probe.log") == 0
    cmd = [PY, str(SRC / "torch/generate_corpus.py"), "--out", str(OUT / "corpus"), "--judges", "audiobox"]
    if MODE == "smoke":
        cmd += ["--only", *SMOKE_IDS]
    summary["corpus_exit"] = sh(cmd, "corpus.log")
    if summary["cmi_ok"]:
        summary["cmi_exit"] = sh([VPY, str(SRC / "torch/score_judge.py"), "score", "--judge", "cmi",
                                  "--corpus", str(OUT / "corpus"), "--wavs", str(OUT / "corpus"),
                                  "--out", str(OUT / "judge_cmi.json"), "--repo", str(CMI),
                                  "--ckpt", str(CMI / "baselines/model/model.safetensors")],
                                 "cmi_score.log")
    summary["done"] = len(list((OUT / "corpus").glob("*.json")))
    sh(["bash", "-c", "cd corpus && tar cf ../wavs.tar *.wav && rm -f *.wav"])
    summary["minutes"] = round((time.time() - t0) / 60, 1)
    (OUT / "summary.json").write_text(json.dumps(summary, indent=1))
    print(json.dumps(summary, indent=1))
    sys.exit(int(summary["corpus_exit"] != 0))


